import { test } from "node:test";
import assert from "node:assert/strict";
import { readFileSync } from "node:fs";
import * as sanitizer from "./sanitizer.ts";

// Vectors are generated by ts/tools/gen-render-vectors from Go's real render package (build tag javascript).
interface Pair {
  in: string;
  out: string | null;
}
interface Vectors {
  sanitize: Pair[];
  removeSpace: [string, string][];
  allowAttr: [string, boolean][];
  linkable: [string, boolean][];
}
const data: Vectors = JSON.parse(readFileSync(new URL("./testdata/render_vectors.json", import.meta.url), "utf8"));

test("Sanitize matches Go", () => {
  assert.ok(data.sanitize.length >= 400, "at least 400 vectors");
  for (const v of data.sanitize) {
    assert.equal(sanitizer.Sanitize(v.in), v.out, "input " + JSON.stringify(v.in));
  }
});

test("removeSpace matches Go", () => {
  for (const [s, out] of data.removeSpace) {
    assert.equal(sanitizer.removeSpace(s), out, "input " + JSON.stringify(s));
  }
});

test("allowAttr matches Go", () => {
  for (const [s, out] of data.allowAttr) {
    assert.equal(sanitizer.allowAttr(s), out, "input " + JSON.stringify(s));
  }
});

test("linkable matches Go", () => {
  for (const [s, out] of data.linkable) {
    assert.equal(sanitizer.linkable(s), out, "input " + JSON.stringify(s));
  }
});
